import { Slot } from '@radix-ui/react-slot'
import { cva, type VariantProps } from 'class-variance-authority'
import * as React from 'react'
import { cn } from '@/lib/utils'

const buttonVariants = cva(
  "inline-flex items-center justify-center gap-2 whitespace-nowrap rounded-md text-sm font-medium disabled:pointer-events-none disabled:opacity-50 [&_svg]:pointer-events-none [&_svg:not([class*='size-'])]:size-4 shrink-0 [&_svg]:shrink-0 [outline:1px_solid_transparent] [outline-offset:-1px] transition-[outline-color,box-shadow,background-color,color] focus-visible:[outline-color:var(--color-ring)] aria-invalid:ring-destructive/20 dark:aria-invalid:ring-destructive/40 aria-invalid:border-destructive",
  {
    variants: {
      variant: {
        default:
          'bg-selected text-selected-foreground shadow-[0_1px_2px_0_rgb(0_0_0/0.05),inset_0_0_0_2px_transparent] hover:bg-selected/90 focus-visible:shadow-[0_1px_2px_0_rgb(0_0_0/0.05),inset_0_0_0_2px_var(--color-background)]',
        destructive:
          'bg-destructive text-white shadow-[0_1px_2px_0_rgb(0_0_0/0.05),inset_0_0_0_2px_transparent] hover:bg-destructive/90 dark:bg-destructive/60 focus-visible:shadow-[0_1px_2px_0_rgb(0_0_0/0.05),inset_0_0_0_2px_var(--color-background)]',
        outline:
          'border border-input bg-background shadow-xs hover:bg-accent hover:text-accent-foreground dark:bg-input/30 dark:border-input dark:hover:bg-input/50',
        secondary:
          'bg-secondary text-secondary-foreground shadow-xs hover:bg-secondary/80',
        ghost:
          'hover:bg-accent hover:text-accent-foreground dark:hover:bg-accent/50',
        link: 'text-primary underline-offset-4 hover:underline',
        attribute:
          'border border-border bg-transparent text-muted-foreground hover:border-border/80 hover:text-foreground',
      },
      size: {
        default: 'h-9 px-4 py-2 has-[>svg]:px-3',
        sm: 'h-8 rounded-md gap-1.5 px-3 has-[>svg]:px-2.5',
        lg: 'h-10 rounded-md px-6 has-[>svg]:px-4',
        icon: 'size-9',
        'icon-sm': 'size-7 rounded-md [&_svg:not([class*=size-])]:size-3.5',
        pill: 'h-7 px-2.5 rounded-full gap-1.5 text-xs [&_svg:not([class*=size-])]:size-3.5',
        'pill-icon': 'size-7 rounded-full [&_svg:not([class*=size-])]:size-3.5',
        'pill-lg': 'h-8 px-4 rounded-full text-sm',
      },
    },
    defaultVariants: {
      variant: 'default',
      size: 'default',
    },
  }
)

export interface ButtonProps
  extends React.ButtonHTMLAttributes<HTMLButtonElement>,
    VariantProps<typeof buttonVariants> {
  asChild?: boolean
}

const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
  ({ className, variant, size, asChild = false, ...props }, ref) => {
    const Comp = asChild ? Slot : 'button'
    return (
      <Comp
        className={cn(buttonVariants({ variant, size, className }))}
        ref={ref}
        {...props}
      />
    )
  }
)
Button.displayName = 'Button'

export { Button, buttonVariants }
